import type { ReactNode } from 'react'
import { Box, Icon, Link } from '@chakra-ui/react'
import type { LinkProps } from '@chakra-ui/react'

import { AiOutlineExport } from 'react-icons/ai'

/** @jsxImportSource @emotion/react */
import { css } from '@emotion/react'


type Prop = LinkProps & {
  children: ReactNode;
  imgWidth?: string;
}
export function MyLink(prop: Prop) {
  const { children,  imgWidth, ...otherProp } = prop;
  
  const divStyle = imgWidth? styles.div(imgWidth) : undefined;
  
  // otherPropで指定された属性のうち、このComponentで指定している属性は無視する（優先度低とするため、より左側で適用する(※)）
  // ※ 通常のHTMLタグであれば、左側の方が優先度高だが、JSXでのJS処理では左側が優先度低
  return (
    <Link 
      css={[styles.link, divStyle]}
      colorPalette='teal' variant='underline' 
      target='_blank' rel='noopener noreferrer' 
      {...otherProp}
      >
      <Box as='div'>
        {children}
        <Icon className='icon'>
          <AiOutlineExport />
        </Icon>
      </Box>
    </Link>
  )
}

const styles = {
  link: css`
    width: fit-content;
    margin-inline: 5px;
    
    > div {
      display: inline-flex;
      .icon {
        margin: 0 3px 0 5px;
      }
    }
    
    > div:has(img) {
      position: relative;
      .icon {
        position: absolute;
        right: 0;
        top: 3px;
        
        mix-blend-mode: difference;
      }
    }
  `,
  div: (width: string) => css`
    width: ${width};
    > div {
      width: 100%;
      > img {
        width: 100%;
      }
    }
  `
}

